from pathlib import Path
import markdown

HERE = Path(__file__).resolve().parent
def render(name):
    return markdown.markdown((HERE/name).read_text(encoding='utf-8'),extensions=['fenced_code','tables']).replace('<h1>','<h2>').replace('</h1>','</h2>')
def pair(key, first, second, a, b):
    return f'''<div class="comparison"><fieldset><legend>Keep the camera fixed</legend><label><input type="radio" name="{key}" checked> {a}</label><label><input id="{key}-second" type="radio" name="{key}"> {b}</label></fieldset>
<figure class="before"><img src="figures/{first}.png" alt="{a}" loading="lazy"><figcaption>{a}</figcaption></figure>
<figure class="after"><img src="figures/{second}.png" alt="{b}" loading="lazy"><figcaption>{b}</figcaption></figure></div>'''

html = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wall relations · Ada / Gillick</title><style>
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f1eee8;color:#292c31;font:18px/1.65 system-ui,sans-serif}header,main,footer{max-width:1240px;margin:auto;padding:30px}header{padding-top:65px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:#81516b}h1,h2,h3{font-family:Georgia,serif;font-weight:400;line-height:1.12}h1{font-size:clamp(46px,8vw,92px);margin:20px 0}h2{font-size:40px}h3{font-size:29px}.lead{font:27px/1.5 Georgia,serif;max-width:880px}a{color:#843651;text-underline-offset:4px}nav{display:flex;flex-wrap:wrap;gap:25px}section{border-top:1px solid #c9c3b9;padding:38px 0;scroll-margin-top:15px}figure{margin:25px 0}img{display:block;width:100%;height:auto}figcaption,.small{font:14px/1.6 system-ui;color:#585b61}figcaption{padding-top:9px}article{max-width:760px;margin:auto;font:24px/1.75 Georgia,serif}.making{max-width:850px;margin:auto}pre{background:#242b31;color:#f3e8ec;padding:22px;overflow:auto;font:15px/1.6 Consolas,monospace}code{font-size:.9em}fieldset{border:0;padding:12px 0;display:flex;gap:15px;flex-wrap:wrap}legend{font-size:13px;text-transform:uppercase;letter-spacing:.1em}label{cursor:pointer;padding:8px 14px;background:#e5ddd8;border:1px solid #c6bcb8;border-radius:3px}label:has(input:checked){background:#f3d8e4;border-color:#963b69}input{accent-color:#963b69}.after{display:none}.comparison:has(input[id]:checked) .before{display:none}.comparison:has(input[id]:checked) .after{display:block}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}.pill{display:inline-block;padding:12px 20px;background:#2b3037;color:#f4eaef;text-decoration:none}td,th{text-align:left;padding:14px;border-bottom:1px solid #cac3b9;vertical-align:top}table{border-collapse:collapse;width:100%;font-size:16px}details{border:1px solid #cac3b9;padding:20px}summary{cursor:pointer}footer{font-size:14px;border-top:1px solid #cac3b9}@media(max-width:700px){header,main,footer{padding:22px}article{font-size:21px}.pair{grid-template-columns:1fr}label{font-size:14px}table{font-size:13px}td,th{padding:7px}}
</style></head><body><header><div class="eyebrow">Ada · Colour / wall companions · 2 October 2026</div><h1>Wall relations.</h1><p class="lead">A bar, an interval, a crossing. The wall becomes part of what we are looking at.</p><nav><a href="#room">Three studies</a><a href="#reading">Read</a><a href="#making">Make a change</a><a href="#references">References</a></nav><p class="small">Original Godot studies informed by Liam Gillick. Proposed companions for Color_Walls.</p></header><main>
<section id="room"><figure><img src="figures/wall-overview.png" width="1800" height="1200" alt="Three original coloured wall structures in a Godot gallery"><figcaption>Native Godot gallery: Intervals, Crossings, Open line. These companions are not yet installed in the museum.</figcaption></figure>
<h2>1. Open the intervals</h2><p>The same 24 bars, colours and dimensions. Increasing their pitch gives the wall more room between them.</p>''' + pair('intervals','intervals-tight','intervals-open','Tight · 0.11 m pitch','Open · 0.21 m pitch') + '''
<h2>2. Bring the crossing forward</h2><p>Six vertical members move towards you. Their horizontal and vertical coordinates stay fixed; perspective, occlusion and shadows respond to their depth.</p>''' + pair('crossings','crossings-shallow','crossings-deep','Shallow crossing','Deep crossing') + '''
<figure><img src="figures/crossings-oblique.png" alt="An oblique view reveals separated layers of coloured bars and their shadows" loading="lazy"><figcaption>The oblique view exposes the gap between the two directions. The projection is an authored change, not a simulated joint or material force.</figcaption></figure>
<h2>3. Omit one rail</h2><p>Twelve segments suggest a process diagram. Remove the upper member and watch the outline open. The wall remains solid.</p>''' + pair('line','line-complete','line-omitted','All twelve segments','One address left empty') + '''
<h2>Let one colour hold the differences</h2><p>Keep the open intervals and deep crossing. Only the colour assignment changes.</p>''' + pair('colour','wall-sequence','wall-pink','Six-colour sequence','All pink') + '''
<p><a class="pill" href="wall-relations-study.zip" download>Download the playable Godot study</a></p><p class="small">Godot 4.6 · import project.godot and run · fixed views or WASD + mouse · Escape releases the pointer · Reset restores the start.</p></section>
<section id="reading"><article>''' + render('READING.md') + '''</article></section><section id="making"><div class="making">''' + render('MAKING.md') + '''</div></section>
<section id="references"><h2>The references are specific. The responses are ours.</h2><table><thead><tr><th>Gillick reference</th><th>What we try</th></tr></thead><tbody>
<tr><td><a href="https://www.kerlingallery.com/artists/liam-gillick">Reached Horizon, 2017</a></td><td>Serial elements and the wall between them. Our 24 vertical bars change orientation, count, scale and palette.</td></tr>
<tr><td><a href="https://www.kerlingallery.com/fairs/art-sg">Extended Complex, 2022</a></td><td>An enlarged crossing of coloured members, with a depth control of our own.</td></tr>
<tr><td><a href="https://caseykaplangallery.com/?exhibitions=liam-gillick-3">Fact Structures Amount Structures Language Structures, 2024</a></td><td>Open linear compositions and industrial extrusion. Our rail layout and omission rule are invented.</td></tr></tbody></table>
<p>The 2024 exhibition links these components to production and its representation. In Ada, understanding the geometry gives us a way into that question; it does not supply a factory, its labour or its politics.</p><p>These are proposed returns in <strong>Colour → Color_Walls</strong>, using Line, Coordinates, Transformation and Array. The short reading, the spatial encounter and the small learner edit remain separate.</p>
<details><summary>Evidence and source files</summary><p>19 native behaviour checks and 12 image saves passed. The tests cover controls, persistent identities, independent colour and geometry, collision removal/restoration, proximity guard and reset. No headset or physical-keyboard test.</p><p><a href="figures/verification.json">Native checks</a> · <a href="figures/provenance.json">Source hashes</a> · <a href="README.md">Reference notes and limits</a> · <a href="READING.md">Reading</a> · <a href="MAKING.md">Making</a></p></details></section></main>
<footer>Ada Research · <a href="../2026-10-02-gillick-room-to-gather/index.html#room">Return to Room to gather</a> · <a href="/tutorial-lineage">Tutorial lineage</a></footer></body></html>'''
(HERE/'index.html').write_text(html,encoding='utf-8')
